     "data": {
       "labels": ["不超过35平方毫米", "35-50平方毫米", "50-95平方毫米", "95-185平方毫米", "185-300平方毫米", "300-500平方毫米", "超过500平方毫米"],
       "datasets": [
         {
           "label": "主接地支线最小尺寸",
